$erro='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$nome=trim((string)($_POST['nome']??''));$email=trim((string)($_POST['email']??''));$senha=(string)($_POST['senha']??'');if($nome===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($senha)<12)$erro='Informe nome, e-mail válido e senha com ao menos 12 caracteres.';else {try{$q=db()->prepare('INSERT INTO usuarios_admin(nome,email,senha_hash) VALUES(?,?,?)');$q->execute([$nome,$email,password_hash($senha,PASSWORD_DEFAULT)]);echo 'Administrador criado. EXCLUA admin/criar_admin.php e acesse <a href="login.php">login</a>.';exit;}catch(Throwable $e){$erro='Não foi possível criar administrador.';}}}
